// Mirrors instance A's OWN did.json verbatim, including its real public
// key, so a challenge-response signed with A's real private key genuinely
// verifies against it (the whole point of the synthetic-peer trick) — for
// Host dcs-orce. Host dcs-orce-mismatch (ADR-19 AC5) is a DIFFERENT,
// static, offline-generated identity with its own P-256 test key (see the
// tab info) and takes the second output instead of fetching A at all.
// Host dcs-orce-trusted (ADR-19 AC7/AC8/AC9) is a third identity, generated
// per BDD run and published through POST /synthetic-trusted/identity, and
// takes the third output.
const host = (msg.req && msg.req.headers && msg.req.headers.host) || '';
if (host.indexOf('dcs-orce-mismatch') === 0) {
  return [null, msg, null];
}
if (host.indexOf('dcs-orce-trusted') === 0) {
  return [null, null, msg];
}
// did.json is mounted on the root mux, OUTSIDE DCS_API_PATH (did:web
// semantics) — DCS_URL (shared with contract-target-flow.json) carries the
// API base path for ITS OWN callback legs, so strip any path back down to
// the bare origin here rather than reusing it verbatim.
const raw = env.get('DCS_URL') || 'http://dcs-digital-contracting-service:8991';
const origin = (raw.match(/^https?:\/\/[^/]+/) || [raw])[0];
msg.url = origin + '/.well-known/did.json';
msg.method = 'GET';
return [msg, null, null];

msg.headers = { "Content-Type": "application/did+json" };
if (msg.statusCode >= 200 && msg.statusCode < 300) {
  msg.statusCode = 200;
} else {
  msg.statusCode = 502;
  msg.payload = { error: "could not fetch instance A's did.json", upstreamStatus: msg.statusCode };
}
return msg;

// Host dcs-orce (the plain synthetic-peer identity, AC4/AC6): no
// agreement credential at all, 404. Host dcs-orce-mismatch (ADR-19 AC5):
// a genuine, signature-valid static credential whose termsOfUse.hash is
// deliberately wrong — takes the second output instead. Host
// dcs-orce-trusted (ADR-19 AC7/AC8/AC9): the credential published for this
// run, which does name the running build's rules hash — third output.
const host = (msg.req && msg.req.headers && msg.req.headers.host) || '';
if (host.indexOf('dcs-orce-mismatch') === 0) {
  return [null, msg, null];
}
if (host.indexOf('dcs-orce-trusted') === 0) {
  return [null, null, msg];
}
msg.statusCode = 404;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { error: "synthetic peer publishes no agreement credential" };
return [msg, null, null];

// Offline-generated, checked-in static asset (ADR-19 AC5) — a genuine
// P-256 TEST keypair with no relation to any instance's real HSM-held
// identity, generated once via backend/cmd/gensyntheticmismatch (not part
// of the running service) and pasted here verbatim.
const MISMATCH_DID_DOCUMENT = {"@context":["https://www.w3.org/ns/did/v1","https://w3id.org/security/suites/jws-2020/v1"],"assertionMethod":["did:web:dcs-orce-mismatch%3A1880#dev-key-1","did:web:dcs-orce-mismatch%3A1880#dcs-vc"],"id":"did:web:dcs-orce-mismatch%3A1880","verificationMethod":[{"controller":"did:web:dcs-orce-mismatch%3A1880","id":"did:web:dcs-orce-mismatch%3A1880#dev-key-1","publicKeyJwk":{"alg":"ES256","crv":"P-256","kid":"dev-key-1","kty":"EC","x":"qkKH5CWrPWFEcBvF5urE7wr27xCbdP1oEnS_0R82zbI","x5c":[""],"y":"KDRGhcGews4gj7PJBwEBEvLiP_9MKra_cP_atWUcios"},"type":"JsonWebKey2020"},{"controller":"did:web:dcs-orce-mismatch%3A1880","id":"did:web:dcs-orce-mismatch%3A1880#dcs-vc","publicKeyJwk":{"alg":"ES256","crv":"P-256","kid":"dcs-vc","kty":"EC","x":"qkKH5CWrPWFEcBvF5urE7wr27xCbdP1oEnS_0R82zbI","x5c":[""],"y":"KDRGhcGews4gj7PJBwEBEvLiP_9MKra_cP_atWUcios"},"type":"JsonWebKey2020"}]};
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/did+json" };
msg.payload = MISMATCH_DID_DOCUMENT;
return msg;

// Offline-generated, checked-in static asset (ADR-19 AC5): a self-signed
// W3C Verifiable Credential (ecdsa-rdfc-2019 Data Integrity proof, same
// shape federation.BuildAgreementCredential produces) signed with the
// SAME P-256 test key published as this identity's did.json second
// verificationMethod (so the signature genuinely verifies), whose
// termsOfUse.hash is sha256(the embedded rules document + one extra
// byte) — deliberately wrong, not the instance's real federation.Hash().
// Generated once via backend/cmd/gensyntheticmismatch and pasted here
// verbatim; not part of the running service.
const MISMATCH_AGREEMENT_CREDENTIAL = {"@context":["https://www.w3.org/ns/credentials/v2","https://w3id.org/security/data-integrity/v2",{"FederationAgreementCredential":"dcs:FederationAgreementCredential","TrustFrameworkPolicy":"dcs:TrustFrameworkPolicy","dcs":"https://w3id.org/facis/dcs/ontology/v1#","hash":"dcs:rulesHash","policyId":{"@id":"dcs:policyId","@type":"@id"}}],"credentialSubject":{"id":"did:web:dcs-orce-mismatch%3A1880"},"id":"urn:dcs:vc:cba77f1d15a39e3cb05889c8344ac427c6a4893f609d428bbede0e5997ca67c8","issuer":"did:web:dcs-orce-mismatch%3A1880","proof":{"created":"2026-07-23T13:17:26Z","cryptosuite":"ecdsa-rdfc-2019","proofPurpose":"assertionMethod","proofValue":"z25jS5ctcsnXZNjgYMnk96hBAXCj6Le452FQRNitNqRVVjt9iPN2gB3hxUToM3RCPhUWAiKQucVHGPWM6gVgFakC4","type":"DataIntegrityProof","verificationMethod":"did:web:dcs-orce-mismatch%3A1880#dcs-vc"},"termsOfUse":{"hash":"b7ca5b79b22d8e3189c13a3dd82f08e7ed069189392698f1f48944d71dfecc1e","policyId":"http://dcs-orce-mismatch:1880/.well-known/dcs-federation-rules.md","type":"TrustFrameworkPolicy"},"type":["VerifiableCredential","FederationAgreementCredential"],"validFrom":"2026-07-23T13:17:26Z"};
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = MISMATCH_AGREEMENT_CREDENTIAL;
return msg;

// Serves the did.json the harness published for this run (see the "Store
// published trusted identity" node). Nothing is checked in for this
// identity: its agreement credential has to name the RUNNING build's
// federation rules hash, which a static asset stops doing the day
// federation/rules.md changes.
const published = flow.get('trusted_identity');
msg.headers = { "Content-Type": "application/did+json" };
if (!published || !published.didDocument) {
  msg.statusCode = 404;
  msg.payload = { error: "no trusted synthetic peer identity published — POST /synthetic-trusted/identity first" };
} else {
  msg.statusCode = 200;
  msg.payload = published.didDocument;
}
return msg;

// Serves the agreement credential the harness published for this run: it is
// issued by this identity's own DID, signed with the VC key the did.json
// above publishes, and names the running build's federation rules hash — so
// the receiving instance's layer-3a check passes and the PDP is the only
// gate left (ADR-19 AC7/AC8/AC9).
const published = flow.get('trusted_identity');
msg.headers = { "Content-Type": "application/json" };
if (!published || !published.agreementCredential) {
  msg.statusCode = 404;
  msg.payload = { error: "no trusted synthetic peer identity published — POST /synthetic-trusted/identity first" };
} else {
  msg.statusCode = 200;
  msg.payload = published.agreementCredential;
}
return msg;

// Control surface for the dcs-orce-trusted identity: the BDD harness mints a
// P-256 key pair, self-signs the agreement credential over the rules hash the
// instance under test currently publishes, and pushes both documents here.
const body = msg.payload || {};
msg.headers = { "Content-Type": "application/json" };
if (!body.didDocument || !body.didDocument.id || !body.agreementCredential) {
  msg.statusCode = 400;
  msg.payload = { error: "expected {didDocument: {id, ...}, agreementCredential: {...}}" };
  return msg;
}
flow.set('trusted_identity', {
  didDocument: body.didDocument,
  agreementCredential: body.agreementCredential
});
msg.statusCode = 200;
msg.payload = { published: body.didDocument.id };
return msg;
